92	      const loop = await repos.loops.getLoop(request.params.id);
93	      if (!loop || loop.ownerId !== request.auth.ownerId)
94	        throw new EngineRequestError('LOOP_NOT_FOUND', `loop ${request.params.id} not found`);
95	      const body = request.body;
