62	  hookRateLimitPerMinute: number;
63	  swaggerUi: boolean;
64	  publicUrl?: string;
65	  /** Path to a `codex` executable. Default: the CLI bundled with `@openai/codex-sdk`. */
66	  codexBinary?: string;
67	  /** Explicit owner-installed native Claude Code executable; never downloaded or substituted. */
68	  claudeBinary?: string;
69	  /** Initial fallback only; the saved gateway-wide Ollama connection takes precedence. */
70	  ollamaEnabled: boolean;
71	  ollamaUrl: string;
72	  /** Absolute path of the built web app to serve under /app/, if configured. */
73	  webDist?: string;
74	  /** Absolute path of the independent Goblin shell served under /goblin/. */
75	  goblinDist?: string;
76	  /** Seeds the local owner's Jev secret at startup only when it is absent. */
77	  jevApiKey?: { value: string; source: 'GG_JEV_API_KEY' | 'JEV_API_KEY' };
78	}
