80	export class ConfigurationUpgradeRequiredError extends Error {
81	  readonly code = 'CONFIGURATION_UPGRADE_REQUIRED';
82	  constructor() {
83	    super(
84	      'Replace GG_DEFAULT_MODEL/GG_DEFAULT_EFFORT with GG_DEFAULTS JSON using {byHarness:{codex:{model,effort}}}',
85	    );
86	    this.name = 'ConfigurationUpgradeRequiredError';
87	  }
88	}
