90	/** The default data directory: `~/.graphgoblin`. */
91	export function defaultDataDir(): string {
92	  return join(homedir(), '.graphgoblin');
93	}
94	
95	/**
96	 * The web app built next to this package in a checkout (`apps/web/dist`, found relative to this
97	 * module in both `src` and `dist`), when its `index.html` exists. `main` uses it as the default
98	 * for `GG_WEB_DIST`, so `pnpm start` serves the UI with no configuration.
99	 */
100	export function bundledWebDist(exists: (path: string) => boolean = existsSync): string | undefined {
101	  const dir = fileURLToPath(new URL('../../web/dist', import.meta.url));
102	  return exists(join(dir, 'index.html')) ? dir : undefined;
103	}
104	
105	export function bundledGoblinDist(
106	  exists: (path: string) => boolean = existsSync,
107	): string | undefined {
108	  const dir = fileURLToPath(new URL('../../web/dist-goblin', import.meta.url));
109	  return exists(join(dir, 'index.html')) ? dir : undefined;
110	}
111	
112	export interface LoadConfigOptions {
113	  /** The web app directory to serve when `GG_WEB_DIST` is unset. */
114	  webDistFallback?: string | undefined;
115	  goblinDistFallback?: string | undefined;
116	}
117	
118	/** Parse configuration from an environment map. Throws with a readable message on bad values. */
119	export function loadConfig(
120	  env: NodeJS.ProcessEnv = process.env,
121	  options: LoadConfigOptions = {},
122	): ApiConfig {
123	  if (env.GG_DEFAULT_MODEL !== undefined || env.GG_DEFAULT_EFFORT !== undefined) {
124	    throw new ConfigurationUpgradeRequiredError();
125	  }
126	  const rawDefaults =
127	    env.GG_DEFAULTS === undefined
128	      ? { byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' } } }
129	      : (JSON.parse(env.GG_DEFAULTS) as unknown);
130	  const defaults = HarnessDefaultsSchema.parse(rawDefaults);
131	  const parsed = EnvSchema.safeParse(env);
132	  if (!parsed.success) {
133	    const issues = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ');
134	    throw new Error(`invalid configuration: ${issues}`);
135	  }
136	  const e = parsed.data;
137	  const dataDir = resolve(e.GG_DATA_DIR || defaultDataDir());
138	  const webDist = e.GG_WEB_DIST ?? options.webDistFallback;
139	  const goblinDist = e.GG_GOBLIN_DIST ?? options.goblinDistFallback;
140	  const jevApiKey = e.GG_JEV_API_KEY ?? env.JEV_API_KEY;
141	  const jevApiKeySource = e.GG_JEV_API_KEY !== undefined ? 'GG_JEV_API_KEY' : 'JEV_API_KEY';
142	  return {
143	    host: e.GG_HOST,
144	    port: e.GG_PORT,
145	    dataDir,
146	    dbUrl: e.GG_DB_URL ?? `file:${resolve(dataDir, 'graphgoblin.db').replace(/\\/g, '/')}`,
147	    requireApiKey: e.GG_REQUIRE_API_KEY,
148	    ...(e.GG_MASTER_KEY ? { masterKey: e.GG_MASTER_KEY } : {}),
149	    logLevel: e.GG_LOG_LEVEL,
150	    maxConcurrentRuns: e.GG_MAX_CONCURRENT_RUNS,
151	    defaults,
152	    timerPollMs: e.GG_TIMER_POLL_MS,
153	    shutdownGraceMs: e.GG_SHUTDOWN_GRACE_MS,
154	    hookRateLimitPerMinute: e.GG_HOOK_RATE_LIMIT,
155	    swaggerUi: e.GG_SWAGGER_UI,
156	    ...(e.GG_PUBLIC_URL !== undefined ? { publicUrl: e.GG_PUBLIC_URL } : {}),
157	    ...(e.GG_CODEX_BINARY ? { codexBinary: e.GG_CODEX_BINARY } : {}),
158	    ...(e.GG_CLAUDE_BINARY ? { claudeBinary: e.GG_CLAUDE_BINARY } : {}),
159	    ollamaEnabled: e.GG_OLLAMA_ENABLED,
