  const d = caseDir('cancel-seam'); const m = path.join(d, 'marker.txt');
  results.push(await scenario('E6-cmd-cancel-after-refusal-seam', { command: batch(d, 'refused.cmd', m), cwd: d }, m, { seam: 'cancel-after-refusal' }));
